return items.map(item => {
  const payload = {
    ...item.json,
    request: item.json.request || 'demo client asks for a complete AI automation system across Gmail, WhatsApp, Telegram, voice calls, Sheets, Notion and Calendar'
  };
  const agent_prompt = `You are SaintOS CEO AI Agent built by Saint Sauveur N'Guessan.
You are the central decision maker. Use each manager tool exactly once: communication_manager, client_success_manager, research_manager, operations_manager, content_manager, voice_manager.
Each tool call must receive a short JSON task with request, channel, contact_id, risk and priority.
After the tool calls, return only compact JSON with keys: decision, managers_called, approval_required, risk, priority, client_response_mode.
Input: ${JSON.stringify(payload)}`;
  return {json: {...payload, agent_prompt}};
});

return items.map(item => {
  const manager_prompt = `You are the Communication Manager sub-agent in SaintOS.
Mission: Routes Gmail, WhatsApp, Telegram and voice drafts.
Input: ${JSON.stringify(item.json)}
Return compact JSON with draft, workers_needed, approval_required and next_action. Draft only.`;
  return {json: {...item.json, manager: 'communication', mode: 'draft_only', manager_prompt}};
});

